"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["72244"],{93547(e){e.exports=JSON.parse('{"id":"F337","slug":"option-price-bounds","name":"Option Price Bounds and Early Exercise Check","subject":"Derivatives","section":"Derivatives","topic":"American vs. European options","level":"Intermediate","aliases":["American option","European option","early exercise","no arbitrage bounds"],"formula":{"latex":"C\\\\ge\\\\max(S e^{-qT}-K e^{-rT},0),\\\\quad P\\\\ge\\\\max(K e^{-rT}-S e^{-qT},0),\\\\quad P_{Amer}\\\\ge K-S","also":[],"text":"European call lower bound = max(S x e^(-qT) - K x e^(-rT), 0); European put lower bound = max(K x e^(-rT) - S x e^(-qT), 0); American put lower bound = max(K - S, 0)"},"symbols":[{"symbol":"S","meaning":"Stock price","unit":"money"},{"symbol":"K","meaning":"Strike","unit":"money"},{"symbol":"r","meaning":"Risk-free rate","unit":"per year"},{"symbol":"q","meaning":"Dividend yield","unit":"per year"},{"symbol":"T","meaning":"Time to expiry","unit":"years"}],"when_to_use":"Use it to test whether an option price is sensible, and to see if early exercise might be worth it. An American option can be exercised any time, so it is worth at least its intrinsic value. If a put\'s intrinsic value exceeds its European lower bound, early exercise can be optimal. A call on a share with no dividends is never exercised early.","worked_example":{"problem":"A stock is at 40 and a put has a strike of 50 and expires in 1 year. The risk-free rate is 5% and there is no dividend. Are early exercise rights valuable for the put?","inputs":{"s":40,"k":50,"r":5,"q":0,"t":1},"steps":[{"label":"European call lower bound = max(S e^(-qT) - K e^(-rT), 0)","working":"max(40 x exp(-0 x 1)-50 x exp(-0.05 x 1), 0)","value":"0.00"},{"label":"European put lower bound = max(K e^(-rT) - S e^(-qT), 0)","working":"max(50 x exp(-0.05 x 1)-40 x exp(-0 x 1), 0)","value":"7.56"},{"label":"American put lower bound = max(K - S, 0)","working":"max(50-40, 0)","value":"10.00"},{"label":"Difference = intrinsic - European floor (positive means early exercise can pay)","working":"10-7.56147","value":"2.44"}],"answer":"A European put must be worth at least 7.56. An American put is worth at least 10.00, which is 2.44 more. Since immediate exercise would pay more than the European floor, it can be best to exercise the American put early. For a call, the European floor is 0.00, and without dividends an American call is worth the same as a European call."},"calculator":{"available":true,"inputs":[{"id":"s","label":"Stock price","unit":"money","type":"number","default":40,"hint":""},{"id":"k","label":"Strike price","unit":"money","type":"number","default":50,"hint":""},{"id":"r","label":"Risk-free rate","unit":"%","type":"number","default":5,"hint":""},{"id":"q","label":"Dividend yield","unit":"%","type":"number","default":0,"hint":""},{"id":"t","label":"Time to expiry","unit":"years","type":"number","default":1,"hint":"","min":0.01}],"checks":[],"steps":[{"id":"clow","label":"European call lower bound = max(S e^(-qT) - K e^(-rT), 0)","expr":"max(s*exp(-q*t)-k*exp(-r*t), 0)","format":"money"},{"id":"plow","label":"European put lower bound = max(K e^(-rT) - S e^(-qT), 0)","expr":"max(k*exp(-r*t)-s*exp(-q*t), 0)","format":"money"},{"id":"intr","label":"American put lower bound = max(K - S, 0)","expr":"max(k-s, 0)","format":"money"},{"id":"gap","label":"Difference = intrinsic - European floor (positive means early exercise can pay)","expr":"intr-plow","format":"money"}],"results":["plow","intr","gap"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"clow":0,"plow":7.561471225035703,"intr":10,"gap":2.438528774964297}},"finder":{"finds":"Sensible price limits and whether early exercise can pay","needs":"Stock, strike, rate, dividend yield, time"},"related":[{"slug":"option-intrinsic-time-value","name":"Option Intrinsic Value and Time Value"},{"slug":"put-call-parity","name":"Put-Call Parity"},{"slug":"black-scholes-merton","name":"Black-Scholes-Merton Option Price"}],"related_ids":["F324","F326","F331"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>C</mi><mo>\u2265</mo><mi>max</mi><mo>\u2061</mo><mo stretchy=\\"false\\">(</mo><mi>S</mi><msup><mi>e</mi><mrow><mo>\u2212</mo><mi>q</mi><mi>T</mi></mrow></msup><mo>\u2212</mo><mi>K</mi><msup><mi>e</mi><mrow><mo>\u2212</mo><mi>r</mi><mi>T</mi></mrow></msup><mo separator=\\"true\\">,</mo><mn>0</mn><mo stretchy=\\"false\\">)</mo><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>P</mi><mo>\u2265</mo><mi>max</mi><mo>\u2061</mo><mo stretchy=\\"false\\">(</mo><mi>K</mi><msup><mi>e</mi><mrow><mo>\u2212</mo><mi>r</mi><mi>T</mi></mrow></msup><mo>\u2212</mo><mi>S</mi><msup><mi>e</mi><mrow><mo>\u2212</mo><mi>q</mi><mi>T</mi></mrow></msup><mo separator=\\"true\\">,</mo><mn>0</mn><mo stretchy=\\"false\\">)</mo><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><msub><mi>P</mi><mrow><mi>A</mi><mi>m</mi><mi>e</mi><mi>r</mi></mrow></msub><mo>\u2265</mo><mi>K</mi><mo>\u2212</mo><mi>S</mi></mrow><annotation encoding=\\"application/x-tex\\">C\\\\ge\\\\max(S e^{-qT}-K e^{-rT},0),\\\\quad P\\\\ge\\\\max(K e^{-rT}-S e^{-qT},0),\\\\quad P_{Amer}\\\\ge K-S</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"option-intrinsic-time-value","name":"Option Intrinsic Value and Time Value"},"next":{"slug":"oos-r-squared","name":"Out-of-Sample R-Squared"},"lesson":null,"total":522}')}}]);